for a0 in 0..32:
    for a1 in 0..64:
        for a2 in 0..64:
            for a3 in 0..64:
                in0 = load input[0, a0, a3]
                in1 = load linear_wt[a3, a2]
                v0 = multiply(in0, in1)
                acc0 <- add(acc0, v0) over a3
            in2 = load linear_1_wt[a2, a1]
            v1 = multiply(acc0, in2)
            acc1 <- add(acc1, v1) over a2
        linear_1[0, a0, a1] = acc1
